INSERT INTO benefit_items_import VALUES
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 1, '滿期', '滿期保險金', '依已繳保費計算（看原文）', '十五、「月繳保險費年化總額」：指以「月繳應繳保險費」的十二倍乘上下列期日所對應之保險單年度所計得之金額：（一）給付「滿期保險金」時：原定繳費期間屆滿日。'),
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 2, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症(初期)或癌症(輕度)保險金', '第2年起：保額 × 20%（第1年內：保費 × 1）', '第十四條初次罹患癌症(初期)或癌症(輕度)保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症(初期)或癌症(輕度)」者，本公司按下列約定之ㄧ，給付「初次罹患癌症(初期)或癌症(輕度)保險金」：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」。二、診斷確定日在第二保險單年度(含)以後：「保險金額」的百分之二十。本契約因第十條或第十二條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症(初期)或癌症(輕度)保險金」最多以給付一次為限。第十五條初次罹患癌症(重度)保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症(重度)」者，本公司按下列約定，給付「初次罹患癌症(重度)保險金」，但被保險人曾得申領「初次罹患癌症(初期)或癌症(輕度)保險金'),
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 3, '初次罹患癌症（重度）', '初次罹患癌症(重度)保險金', '分情況（看原文）', '第十五條初次罹患癌症(重度)保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症(重度)」者，本公司按下列約定，給付「初次罹患癌症(重度)保險金」，但被保險人曾得申領「初次罹患癌症(初期)或癌症(輕度)保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」的一點三倍。'),
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 4, '身故', '身故保險金或喪葬費用保險金', NULL, '（四）給付「身故保險金或喪葬費用保險金」或「完全失能保險金」時：被保險人「身故日」、「完全失能診斷確定日」或「原定繳費期間屆滿日」三者較早屆至之日。'),
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 5, '初次罹患特定癌症', '初次罹患特定癌症保險金', '保額 × 60%', '第十六條初次罹患特定癌症保險金的給付(第二保險單年度起適用)被保險人於本契約有效期間內，符合「初次診斷確定罹患特定癌症」，且診斷確定日在第二保險單年度(含)以後者，本公司按「保險金額」的百分之六十，給付「初次罹患特定癌症保險金」。'),
  ('cathay', '國泰人壽鍾愛守護防癌定期保險', 6, '完全失能', '完全失能保險金', NULL, '前項第一款及第二十七條情形致被保險人成附表一所列完全失能程度之一時，本公司按第十八條的約定給付「完全失能保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 1, '住院手術醫療', '住院手術醫療保險金', '保額 × 附表倍數（再乘增額係數）', '第十一條住院手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按保險單上所記載之「保險金額」(不含其他附約、附加條款、批註條款)乘以手術日當年度之「增額係數」，再乘以手術給付倍數，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 2, '門診手術醫療', '門診手術醫療保險金', '保額 × 附表倍數（再乘增額係數）', '第十二條門診手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按保險單上所記載之「保險金額」(不含其他附約、附加條款、批註條款)乘以手術日當年度之「增額係數」，再乘以手術給付倍數，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 3, '意外住院手術醫療', '意外住院手術醫療保險金', NULL, '第十三條意外住院手術醫療保險金被保險人於本契約有效期間內且保險年齡未滿七十歲者，因傷害經醫師診斷在住院期間必須接受手術治療且已接受手術者，本公司按保險單上所記載之「保險金額」(不含其他附約、附加條款、批註條款)的三倍，乘以手術日當年度之「增額係數」，給付「意外住院手術醫療保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 4, '特定處置', '特定處置保險金', NULL, '第十四條特定處置保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表二所列之特定處置治療且已接受處置者，本公司將按保險單上所記載之「保險金額」(不含其他附約、附加條款、批註條款)，乘以特定處置日當年度之「增額係數」，再乘以特定處置給付倍數，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 5, '意外創傷縫合處置', '意外創傷縫合處置保險金', NULL, '第十五條意外創傷縫合處置保險金被保險人於本契約有效期間內，因意外傷害事故，於醫院或診所接受附表三的意外創傷縫合處置治療者，本公司按保險單上所記載之「保險金額」(不含其他附約、附加條款、批註條款)，乘以意外創傷縫合處置日當年度之「增額係數」，再乘以意外創傷縫合處置給付倍數，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 6, '祝壽', '祝壽保險金', '保額 × 1', '第十七條祝壽保險金被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽真康順手術醫療終身保險(外溢型)', 7, '身故', '身故保險金', '保額 × 1', '第十八條所繳保險費的退還、身故保險金或喪葬費用保險金被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 1, '住院醫療', '住院醫療保險金', '日額 × 天數', '第十二條住院醫療保險金被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院治療者，本公司按保險單上所記載之「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以被保險人住院日數，給付「住院醫療保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 2, '加護病房、燒燙傷病房', '加護病房、燒燙傷病房保險金', '日額 × 3 × 天數（再乘增額係數）', '第十三條加護病房、燒燙傷病房保險金被保險人於本契約有效期間內因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受治療者，除住院醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」的三倍，乘以入院日當年度之「增額係數」，再乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日），給付「加護病房、燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 3, '出院療養', '出院療養保險金', '日額 × 50% × 天數（再乘增額係數）', '第十四條出院療養保險金被保險人於本契約有效期間內因疾病或傷害，而於醫院住院後出院者，除住院醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」的百分之五十，乘以入院日當年度之「增額係數」，再乘以住院日數，給付「出院療養保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 4, '住院手術醫療', '住院手術醫療保險金', '日額 × 3（再乘增額係數）', '第十五條住院手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷在住院期間必須接受手術治療且已接受手術者，本公司按保險單上所記載之「住院醫療保險金日額」的三倍，乘以手術日當年度之「增額係數」，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 5, '門診手術醫療', '門診手術醫療保險金', '日額 × 1（再乘增額係數）', '第十六條門診手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須接受門診手術治療且已接受手術者，本公司按保險單上所記載之「住院醫療保險金日額」乘以手術日當年度之「增額係數」，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 6, '意外住院關懷', '意外住院關懷保險金', '日額 × 3（再乘增額係數）', '第十七條意外住院關懷保險金被保險人於本契約有效期間且保險年齡未滿七十歲時，因傷害而住院診療者，本公司按保險單上所記載之「住院醫療保險金日額」的三倍，乘以入院日當年度之「增額係數」，給付「意外住院關懷保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 7, '祝壽', '祝壽保險金', '保額 × 1', '第十九條祝壽保險金被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽真心安住院醫療終身保險(外溢型)', 8, '身故', '身故保險金', '保額 × 1', '第二十條所繳保險費的退還、身故保險金或喪葬費用保險金被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽真漾心安住院醫療終身保險(外溢型)', 1, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第十六條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽真漾心安住院醫療終身保險(外溢型)', 2, '祝壽', '祝壽保險金', '保額 × 1', '第十五條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽真漾心安住院醫療終身保險(外溢型)', 3, '住院醫療', '住院醫療保險金', '日額 × 天數', '第十二條住院醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院治療者，本公司按保險單上所記載之「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以被保險人住院日數，給付「住院醫療保險金」。'),
  ('cathay', '國泰人壽真漾心安住院醫療終身保險(外溢型)', 4, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', NULL, '第十三條加護病房或燒燙傷病房保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受治療者，除住院醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日）的二倍，給付「加護病房或燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽康泰無憂PLUS住院醫療終身健康保險（外溢型）', 1, '住院手術醫療', '住院手術醫療保險金', '日額 × 3', '第十一條住院手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷在住院期間必須接受手術治療且已接受手術者，本公司按「住院醫療保險金日額」的三倍，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽康泰無憂PLUS住院醫療終身健康保險（外溢型）', 2, '門診手術醫療', '門診手術醫療保險金', NULL, '第十二條門診手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須接受門診手術治療且已接受手術者，本公司按「住院醫療保險金日額」，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽康泰無憂PLUS住院醫療終身健康保險（外溢型）', 3, '住院醫療', '住院醫療保險金', '日額 × 天數', '第十三條住院醫療保險金(第二保險單年度起適用)被保險人因疾病或傷害，而於醫院接受住院診療者，本公司按「住院醫療保險金日額」乘以被保險人住院日數，給付「住院醫療保險金」。'),
  ('cathay', '國泰人壽康泰無憂PLUS住院醫療終身健康保險（外溢型）', 4, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', '日額 × 天數', '第十四條加護病房或燒燙傷病房保險金(第二保險單年度起適用)被保險人因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受治療者，除住院醫療保險金外，本公司另按「住院醫療保險金日額」乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日），給付「加護病房或燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽康泰無憂PLUS住院醫療終身健康保險（外溢型）', 5, '住院慰問', '住院慰問保險金', NULL, '第十五條住院慰問保險金(第二保險單年度起適用)被保險人因疾病或傷害，而於醫院接受住院診療者，本公司按「住院醫療保險金日額」，給付「住院慰問保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 1, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第二十一條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 2, '祝壽', '祝壽保險金', '保額 × 1', '第二十條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 3, '住院日額', '住院日額保險金', '日額 × 天數', '第十二條住院日額保險金被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按下列約定給付「住院日額保險金」：一、被保險人同一次住院診療在三十日(含)以內者，本公司按保險單上所記載之「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以被保險人住院日數，給付「住院日額保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 4, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', NULL, '第十三條加護病房或燒燙傷病房保險金被保險人於本契約有效期間內因疾病或傷害，而入住醫院之加護病房或燒燙傷病房接受治療者，除「住院日額保險金」外，本公司另按「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日）的二倍，給付「加護病房或燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 5, '出院療養', '出院療養保險金', '日額 × 50% × 天數（再乘增額係數）', '第十四條出院療養保險金被保險人於本契約有效期間內因疾病或傷害，而於醫院住院後出院者，本公司另按「住院醫療保險金日額」的百分之五十，乘以入院日當年度之「增額係數」，再乘以實際住院日數計算所得之金額，給付「出院療養保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 6, '住院手術醫療', '住院手術醫療保險金', '日額 × 附表倍數（再乘增額係數）', '第十五條住院手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」乘以手術日當年度之「增額係數」，再乘以住院手術給付倍數，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 7, '門診手術醫療', '門診手術醫療保險金', '日額 × 3（再乘增額係數）', '第十六條門診手術醫療保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」之三倍，乘以手術日當年度之「增額係數」，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 8, '特定處置', '特定處置保險金', '日額 × 附表倍數（再乘增額係數）', '第十七條特定處置保險金被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表二的特定處置治療且已接受處置者，本公司按「住院醫療保險金日額」乘以特定處置日當年度之「增額係數」，再乘以特定處置給付倍數，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽真安安醫療終身保險(外溢型)', 9, '意外創傷縫合處置', '意外創傷縫合處置保險金', '日額 × 附表倍數（再乘增額係數）', '第十八條意外創傷縫合處置保險金被保險人於本契約有效期間內因意外傷害事故，於醫院或診所接受附表三的意外創傷縫合處置治療者，本公司按「住院醫療保險金日額」乘以意外創傷縫合處置日當年度之「增額係數」，再乘以意外創傷縫合處置給付倍數，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 1, '滿期', '滿期保險金', '依已繳保費計算（看原文）', '十五、「月繳保險費年化總額」：指以「月繳應繳保險費」的十二倍乘上下列期日所對應之保險單年度所計得之金額：（一）給付「滿期保險金」時：繳費期間屆滿日。'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 2, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 20%（第1年內：保費 × 1）', '第十四條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之二十。本契約因第十條或第十二條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十五條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 3, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '分情況（看原文）', '第十五條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」的一點三倍。'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 4, '身故', '身故保險金', '保額 × 1', '第十七條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 5, '初次罹患特定癌症', '初次罹患特定癌症保險金', '保額 × 60%', '第十六條初次罹患特定癌症保險金的給付（第二保險單年度起適用）被保險人於本契約有效期間內，符合「初次診斷確定罹患特定癌症」，且診斷確定日在第二保險單年度（含）以後者，本公司按「保險金額」的百分之六十，給付「初次罹患特定癌症保險金」。'),
  ('cathay', '國泰人壽真愛平安防癌定期保險', 6, '意外身故', '意外事故身故保險金', NULL, '第十八條意外事故身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司除依第十七條約定辦理外，另按身故日「保險金額」的兩倍，給付「意外事故身故保險金」。'),
  ('cathay', '國泰人壽享保障重大疾病定期健康保險(甲型)(1年期)', 1, '重大疾病', '重大疾病保險金', '保額 × 1', '第四條保險範圍被保險人於本契約有效期間內罹患第二條約定之「重大疾病」時，本公司按保險單上所記載之保險金額為準，依照本契約約定給付「重大疾病保險金」。'),
  ('cathay', '國泰人壽享保障重大疾病定期健康保險(甲型)(20年期)', 1, '重大疾病', '重大疾病保險金', '保額 × 1', '第五條保險範圍被保險人於本契約有效期間內罹患第二條約定之「重大疾病」時，本公司按保險單上所記載之保險金額為準，依照本契約約定給付「重大疾病保險金」。'),
  ('cathay', '國泰人壽自由配一年定期長期照顧健康保險（外溢型）', 1, '長期照顧', '長期照顧保險金', NULL, '本公司依本條約定給付第一次「長期照顧保險金」後，本契約效力即行終止，惟本公司仍依約定繼續給付「長期照顧保險金」。'),
  ('cathay', '國泰人壽自由配一年定期手術醫療健康保險（外溢型）', 1, '住院手術醫療', '住院手術醫療保險金', '保額 × 10', '第十一條住院手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受手術治療且已實際接受手術者，本公司按「保險金額」的十倍，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽自由配一年定期手術醫療健康保險（外溢型）', 2, '門診手術醫療', '門診手術醫療保險金', '保額 × 2', '第十二條門診手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受手術治療且已實際接受手術者，本公司按「保險金額」的二倍，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽自由配一年定期身故及完全失能壽險', 1, '身故', '身故保險金', '保額 × 1', '第十一條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按保險金額給付身故保險金。'),
  ('cathay', '國泰人壽自由配一年定期身故及完全失能壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十二條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表所列完全失能程度之一者，本公司按保險金額給付完全失能保險金。'),
  ('cathay', '國泰人壽自由配一年定期初次罹患重大傷病健康保險（外溢型）', 1, '重大傷病', '重大傷病保險金', '續保後：保額 × 1（第1年內：保額 × 10%）', '，且已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明，或已取得一家「區域醫院」層級以上（含）之醫療院所開立且符合投保或續保當時「重大傷病範圍」之診斷書及當次「重大傷病」病歷摘要者，本公司按初次診斷確定罹患重大傷病時之保險單年度，以下列方式計算之金額給付「重大傷病保險金」且當期已繳付之未到期保險費將不予退還：一、於投保之保險單年度內初次診斷確定者：保險金額的百分之十。二、於續保之保險單年度內初次診斷確定者：保險金額。被保險人之「重大傷病」如係因意外傷害事故所致者，不受等待期間之限制。第一項情形，被保險人取得「重大傷病」證明時，本契約效力已停止或終止者，本公司仍按約定給付「重大傷病保險金」。被保險人若於本契約有效期間內，喪失全民健康保險被保險人資格，須先申請加保全民健康保險後，始得申領「重大傷病保險金」之給付。被保險人同時或先後罹患二項以上之「重大傷病」，本公司僅給付一項「重大傷病保'),
  ('cathay', '國泰人壽自由配一年定期住院日額醫療健康保險（外溢型）', 1, '住院日額', '住院日額保險金', '日額 × 天數', '第十一條住院日額保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按「住院醫療保險金日額」乘以「住院日數」，給付「住院日額保險金」。'),
  ('cathay', '國泰人壽倍心守護公教長期照顧終身健康保險(外溢型)(實物給付型保險商品)', 1, '特定傷病分期', '特定傷病分期保險金', '保額 × 12', '第十六條特定傷病分期保險金的給付被保險人於本契約等待期間屆滿翌日或復效日起的契約有效期間內，經初次診斷確定罹患第二條第八款約定之「特定傷病」時，本公司按「保險事故日」時之「保險金額」的十二倍，給付「特定傷病分期保險金」，其後被保險人於每一「保險事故日之週年日」仍生存者，本公司按「保險事故日」時之「保險金額」的十二倍，給付「特定傷病分期保險金」。'),
  ('cathay', '國泰人壽倍心守護公教長期照顧終身健康保險(外溢型)(實物給付型保險商品)', 2, '長期照顧復健', '長期照顧復健保險金', '保額 × 6', '被保險人於本契約有效期間且保險年齡滿十五歲，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿之翌日，按「保險金額」的六倍，給付「長期照顧復健保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽倍心守護公教長期照顧終身健康保險(外溢型)(實物給付型保險商品)', 3, '特定傷病', '特定傷病保險金', '保額 × 6', '第十五條特定傷病保險金的給付被保險人於本契約等待期間屆滿翌日或復效日起的契約有效期間內，經初次診斷確定罹患第二條第八款約定之「特定傷病」時，本公司按「保險事故日」時之「保險金額」的六倍，給付「特定傷病保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽IN康愛防癌定期健康保險(外溢型)', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 10%（第1年內：保費 × 1.02）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「第一年年繳應繳保險費」的一點零二倍。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之十。本契約因第九條或第十一條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌'),
  ('cathay', '國泰人壽IN康愛防癌定期健康保險(外溢型)', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 1（第1年內：保費 × 1.02）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「第一年年繳應繳保險費」的一點零二倍。二、診斷確定日在第二保險單年度（含）以後：「保險金額」。被保險人於本契約有效期間且於繳費期間內，符合「初次診斷確定罹患癌症（重度）」者，本契約當期已繳付之未到期保險費將不予退還，亦不併入初次罹患癌症（重度）保險金內給付。被保險人如先符合「初次診斷確定罹患癌症（重度）」後符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」或同時符合前述二者，本公司僅給付「初次罹患癌症（'),
  ('cathay', '國泰人壽IN康愛防癌定期健康保險(外溢型)', 3, '初次罹患特定癌症（重度）', '初次罹患特定癌症（重度）保險金', '保額 × 2', '第十四條初次罹患特定癌症（重度）保險金的給付（第二保險單年度起適用）被保險人於本契約有效期間內，符合「初次診斷確定罹患特定癌症（重度）」，且診斷確定日在第二保險單年度（含）以後者，本公司按「保險金額」的二倍，給付「初次罹患特定癌症（重度）保險金」。'),
  ('cathay', '國泰人壽樂康愛防癌定期健康保險(外溢型)', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 10%（第1年內：保費 × 1.02）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「第一年年繳應繳保險費」的一點零二倍。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之十。本契約因第九條或第十一條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌'),
  ('cathay', '國泰人壽樂康愛防癌定期健康保險(外溢型)', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 1（第1年內：保費 × 1.02）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「第一年年繳應繳保險費」的一點零二倍。二、診斷確定日在第二保險單年度（含）以後：「保險金額」。被保險人於本契約有效期間且於繳費期間內，符合「初次診斷確定罹患癌症（重度）」者，本契約當期已繳付之未到期保險費將不予退還，亦不併入初次罹患癌症（重度）保險金內給付。被保險人如先符合「初次診斷確定罹患癌症（重度）」後符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」或同時符合前述二者，本公司僅給付「初次罹患癌症（'),
  ('cathay', '國泰人壽樂順心手術醫療定期健康保險(外溢型)', 1, '住院手術醫療', '住院手術醫療保險金', '分情況（看原文）', '第十一條住院手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司以下列方式給付「住院手術醫療保險金」：一、第一保險單年度:「保險金額」的零點五倍乘以附表一的手術給付倍數。'),
  ('cathay', '國泰人壽樂順心手術醫療定期健康保險(外溢型)', 2, '門診手術醫療', '門診手術醫療保險金', '分情況（看原文）', '第十二條門診手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司以下列方式給付「門診手術醫療保險金」：一、第一保險單年度:「保險金額」的零點五倍乘以附表一的手術給付倍數。'),
  ('cathay', '國泰人壽樂順心手術醫療定期健康保險(外溢型)', 3, '特定處置', '特定處置保險金', '分情況（看原文）', '第十三條特定處置保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表二所列之特定處置治療且實際已接受處置者，本公司以下列方式給付「特定處置保險金」：一、第一保險單年度:「保險金額」的零點五倍乘以附表二的特定處置給付倍數。'),
  ('cathay', '國泰人壽輕漾心安住院醫療終身健康保險(外溢型)', 1, '住院醫療', '住院醫療保險金', '日額 × 天數', '第十一條住院醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按保險單上所記載之「住院醫療保險金日額」乘以入院日當年度之「增額係數」，再乘以被保險人住院日數，給付「住院醫療保險金」。'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 1, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第二十條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 2, '住院日額', '住院日額保險金', '第2年起：日額 × 天數（第1年：日額 × 0.5 × 天數）', '第十二條住院日額保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司以被保險人住院首日之保險單年度，按下列約定計算給付「住院日額保險金」：一、第一保險單年度：「住院醫療保險金日額」的零點五倍乘以住院日數。二、第二保險單年度以後：「住院醫療保險金日額」乘以住院日數。被保險人同一次住院之「住院日額保險金」合計給付日數最高以一百二十日為限。第十三條住院關懷保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，除「住院日額保險金」外，本公司以被保險人住院首日之保險單年度，另按下列約定計算給付「住院關懷保險金」：一、第一保險單年度：「住院醫療保險金日額」的一點五倍。二、第二保險單年度以後：「住院醫療保險金日額」的三倍。被保險人同一次住院'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 3, '住院關懷', '住院關懷保險金', '第2年起：日額 × 3（第1年：日額 × 1.5）', '第十三條住院關懷保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，除「住院日額保險金」外，本公司以被保險人住院首日之保險單年度，另按下列約定計算給付「住院關懷保險金」：一、第一保險單年度：「住院醫療保險金日額」的一點五倍。二、第二保險單年度以後：「住院醫療保險金日額」的三倍。被保險人同一次住院本公司僅給付一次「住院關懷保險金」。第十四條加護病房或燒燙傷病房保險金的給付被保險人於本契約有效內因疾病或傷害，而入住醫院之加護病房或燒燙傷病房接受診療者，除「住院日額保險金」外，本公司另以被保險人住院首日之保險單年度，按下列約定計算給付「加護病房或燒燙傷病房保險金」：一、第一保險單年度：「住院醫療保險金日額」乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日）。二、第二保險單年度以'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 4, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', '第2年起：日額 × 2 × 天數（第1年：日額 × 天數）', '第十四條加護病房或燒燙傷病房保險金的給付被保險人於本契約有效內因疾病或傷害，而入住醫院之加護病房或燒燙傷病房接受診療者，除「住院日額保險金」外，本公司另以被保險人住院首日之保險單年度，按下列約定計算給付「加護病房或燒燙傷病房保險金」：一、第一保險單年度：「住院醫療保險金日額」乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日）。二、第二保險單年度以後：按「住院醫療保險金日額」的二倍乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日）。被保險人同一次住院之「加護病房或燒燙傷病房保險金」最高給付日數以三十日為限。但同一日內本公司僅就加護病房或燒燙傷病房其中一種病房給付。第十五條住院手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受手術治療且已實際接受手術者，本公司以被保險人接受手術當日之保險單年度'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 5, '住院手術醫療', '住院手術醫療保險金', '第2年起：日額 × 3（第1年：日額 × 1.5）', '第十五條住院手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受手術治療且已實際接受手術者，本公司以被保險人接受手術當日之保險單年度，按下列約定計算給付「住院手術醫療保險金」：一、第一保險單年度：「住院醫療保險金日額」的一點五倍。二、第二保險單年度以後：「住院醫療保險金日額」的三倍。被保險人於同一次手術中，於同一手術位置接受二項以上手術項目時，僅給付一項「住院手術醫療保險金」。第十六條門診手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受手術治療且已實際接受手術者，本公司以被保險人接受手術當日之保險單年度，按下列約定計算給付「門診手術醫療保險金」：一、第一保險單年度：「住院醫療保險金日額」的零點五倍。二、第二保險單年度以後：「住院醫療保險金日'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 6, '門診手術醫療', '門診手術醫療保險金', '分情況（看原文）', '第十六條門診手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受手術治療且已實際接受手術者，本公司以被保險人接受手術當日之保險單年度，按下列約定計算給付「門診手術醫療保險金」：一、第一保險單年度：「住院醫療保險金日額」的零點五倍。'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 7, '骨折', '骨折保險金', '日額 × 10', '第十七條骨折保險金的給付被保險人於本契約有效期間內因傷害，自意外傷害事故發生之日起一百八十日以內，經登記合格的「醫院」、「診所」（不含國術館、接骨所）診斷致成附表所列骨折項目之一（含該項目之完全骨折、不完全骨折及骨骼龜裂）者，本公司按「住院醫療保險金日額」的十倍給付「骨折保險金」。'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 8, '醫材補助', '醫材補助保險金', '第3年起：日額 × 20（第1-2年：日額 × 10）', '第十八條醫材補助保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須且已實際接受第二項手術之一者，本公司依被保險人接受手術當日之保險單年度，按下列約定計算給付「醫材補助保險金」：一、第一及第二保險單年度：「住院醫療保險金日額」的十倍。二、第三保險單年度及以後：「住院醫療保險金日額」的二十倍。前項所稱之手術如下：一、人工水晶體植入術。二、全膝關節置換術或人工全膝關節再置換手術。三、全股關節置換術或人工全髖關節再置換手術。四、心臟血管支架置放術。五、心律調節器植入術。六、腦室腹腔分流手術。七、心室輔助裝置植入術。八、「兩個瓣膜換置手術」、「三個瓣膜換置手術」或「主動脈瓣或二尖瓣或三尖瓣之置換手術」。被保險人於本契約有效期間內，醫材補助保險金之給付以十次為限。第十九條醫療保險金給付總額之上限本'),
  ('cathay', '國泰人壽樂心安住院醫療定期保險(外溢型)', 9, '未住院無理賠回饋', '未住院無理賠回饋保險金', NULL, '第二十一條未住院無理賠回饋保險金的給付被保險人於本契約有效期間內，每逢保險單年度末仍生存，且於該保險單年度內未曾因疾病或傷害於醫院接受住院診療而申領第十二條至第十五條之各項醫療保險金時，本公司按「住院醫療保險金日額」，給付「未住院無理賠回饋保險金」。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 1, '重大傷病', '重大傷病保險金', '分情況（看原文）', '傷病」，且已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明，或已取得一家「區域醫院」層級以上（含）之醫療院所開立且符合投保當時「重大傷病範圍」之診斷書及當次「重大傷病」病歷摘要者，本公司按初次診斷確定罹患重大傷病時之保險單年度，以下列方式計算之金額給付「重大傷病保險金」：一、初次診斷確定罹患重大傷病時之保險單年度為第一保險單年度：「年繳應繳保險費總額」的一點零五倍。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 2, '身故', '身故保險金或喪葬費用保險金', '依已繳保費計算（看原文）', '十二、「年繳應繳保險費總額」：指以本契約「保險金額」為準，按年繳繳費方式無息計算下列期間所應繳保險費總額：（一）給付「身故保險金或喪葬費用保險金」或「完全失能保險金」時：自本契約生效日起至「被保險人身故日、完全失能診斷確定日」或「原定繳費期間屆滿日」二者較早屆至之日。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 3, '滿期', '滿期保險金', NULL, '第十五條滿期保險金的給付被保險人於本契約有效期間且在保險單上所記載保險期間屆滿時（被保險人保險年齡到達九十歲之保險單週年日）仍生存者，本公司按保險期間屆滿時，下列二款計算方式所得金額之較大者，給付「滿期保險金」：一、「當年度保險金額」。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 4, '特定疾病', '特定疾病保險金', '分情況（看原文）', '第十四條特定疾病保險金的給付被保險人於本契約等待期間屆滿翌日或復效日起的契約有效期間內，經初次診斷確定罹患「特定疾病」時，本公司按下列方式計算之金額給付「特定疾病保險金」：一、初次診斷確定罹患「特定疾病」時之保險單年度為第一保險單年度：「年繳應繳保險費總額」的一點零五倍。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 5, '特定重大傷病', '特定重大傷病保險金', '保額 × 20%', '第十三條特定重大傷病保險金的給付被保險人於本契約第二保險單年度(含)以後的有效期間內，經初次診斷確定罹患「特定重大傷病」時，本公司除給付重大傷病保險金外，另按「保險金額的百分之二十」，給付「特定重大傷病保險金」。'),
  ('cathay', '國泰人壽新鍾心滿福重大傷病定期保險(外溢型)', 6, '完全失能', '完全失能保險金', NULL, '第十七條完全失能保險金的給付被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司按完全失能診斷確定日時，下列二款計算方式所得金額之較大者，給付「完全失能保險金」：一、「當年度保險金額」。'),
  ('cathay', '國泰人壽樂齡守護長期照顧定期健康保險(外溢型)(實物給付型保險商品)', 1, '長期照顧一次', '長期照顧一次保險金', '保額 × 6', '第十一條長期照顧一次保險金的給付被保險人於本契約有效期間，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿之翌日，按當時之「保險金額」的六倍，給付「長期照顧一次保險金」。'),
  ('cathay', '國泰人壽樂無憂防癌定期健康保險', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 20%（第1年內：保費 × 1）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之ㄧ，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日於第一保險單年度以內：「月繳保險費年化總額」。二、診斷確定日於第二保險單年度（含）以後：「保險金額」的百分之二十。本契約因第九條或第十一條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金'),
  ('cathay', '國泰人壽樂無憂防癌定期健康保險', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '分情況（看原文）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日於第一保險單年度以內：「月繳保險費年化總額」的一點三倍。'),
  ('cathay', '國泰人壽樂無憂防癌定期健康保險', 3, '癌症（重度）追蹤照護', '癌症（重度）追蹤照護保險金', '保額 × 10%', '第十四條癌症（重度）追蹤照護保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」，自「初次診斷確定罹患癌症（重度）」診斷確定日的次一保險單週年日起，每逢各保險單週年日或保險期間屆滿仍生存者，本公司按「保險金額」的百分之十，給付「癌症（重度）追蹤照護保險金」。'),
  ('cathay', '國泰人壽樂無憂防癌定期健康保險', 4, '癌症（重度）標靶藥物治療補助', '癌症（重度）標靶藥物治療補助保險金', '保額 × 10%', '第十五條癌症（重度）標靶藥物治療補助保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，診斷確定罹患「癌症（重度）」，且於醫院實際注射或口服「標靶治療藥物」接受「標靶治療」者，本公司按「保險金額」的百分之十，給付「癌症（重度）標靶藥物治療補助保險金」。'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 1（第1年內：保額 × 10%）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司以診斷確定日為準，按下列約定，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、第一保險單年度以內：「保險金額」的百分之十。二、第二保險單年度（含）以後：「保險金額」。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司以診斷確定日為準，按下列約定，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、第一保險單年度以內：「保險金額」的百分之五十。二、第二保險單年度（含）以後：「保險金額」的五倍。被保險'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 5（第1年內：保額 × 50%）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司以診斷確定日為準，按下列約定，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、第一保險單年度以內：「保險金額」的百分之五十。二、第二保險單年度（含）以後：「保險金額」的五倍。被保險人如先符合「初次罹患癌症（重度）」後符合「初次罹患癌症（初期）或癌症（輕度）」，或同時符合前述二者，本公司僅給付「初次罹患癌症（重度）保險金」。「初次罹患癌症（重度）保險金」最多以給付一次為限。第十四條癌症住院手術醫療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，於醫院住院並接受以癌症為直接原因或癌症引起的併發症治'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 3, '癌症住院手術醫療', '癌症住院手術醫療保險金', '第2年起：保額 × 2（第1年內：保額 × 20%）', '第十四條癌症住院手術醫療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，於醫院住院並接受以癌症為直接原因或癌症引起的併發症治療手術者，本公司以實際接受「癌症住院手術」日期為準，按下列約定，給付「癌症住院手術醫療保險金」：一、第一保險單年度以內：「保險金額」的百分之二十。二、第二保險單年度（含）以後：「保險金額」的二倍。「癌症住院手術醫療保險金」最多以給付一次為限。第十五條癌症門診手術醫療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，未住院而在醫院門診時接受以癌症為直接原因或癌症引起的併發症治療手術者，本公司以實際接受「癌症門診手術」日期為準，按下列約定，給付「癌症門診手術醫療保險金」：一、第一保險單年度以內：「保險金額」的百分之一。二、第二保險單年度（含）以後：「保險金額」的百分之十。「癌症門診手術醫療保險金'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 4, '癌症門診手術醫療', '癌症門診手術醫療保險金', '第2年起：保額 × 10%（第1年內：保額 × 1%）', '第十五條癌症門診手術醫療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，未住院而在醫院門診時接受以癌症為直接原因或癌症引起的併發症治療手術者，本公司以實際接受「癌症門診手術」日期為準，按下列約定，給付「癌症門診手術醫療保險金」：一、第一保險單年度以內：「保險金額」的百分之一。二、第二保險單年度（含）以後：「保險金額」的百分之十。「癌症門診手術醫療保險金」最多以給付十次為限。第十六條癌症（重度）標靶藥物治療補助保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，且於醫院實際注射或口服「標靶治療藥物」接受「標靶治療」者，本公司以首次接受「標靶治療」之日期為準，按下列約定，給付「癌症（重度）標靶藥物治療補助保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 5, '癌症（重度）標靶藥物治療補助', '癌症（重度）標靶藥物治療補助保險金', '第2年起：保額 × 3（第1年內：保額 × 30%）', '第十六條癌症（重度）標靶藥物治療補助保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，且於醫院實際注射或口服「標靶治療藥物」接受「標靶治療」者，本公司以首次接受「標靶治療」之日期為準，按下列約定，給付「癌症（重度）標靶藥物治療補助保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三倍。「癌症（重度）標靶藥物治療補助保險金」最多以給付一次為限。第十七條癌症（重度）特定粒子精準放射治療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，經醫院醫師指定醫院或機構接受「特定粒子精準放射治療」者，本公司以首次接受「特定粒子精準放射治療」之日期為準，按下列約定，給付「癌症（重度）特定粒子精準放射治療保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 6, '癌症（重度）特定粒子精準放射治療', '癌症（重度）特定粒子精準放射治療保險金', '第2年起：保額 × 3（第1年內：保額 × 30%）', '第十七條癌症（重度）特定粒子精準放射治療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，經醫院醫師指定醫院或機構接受「特定粒子精準放射治療」者，本公司以首次接受「特定粒子精準放射治療」之日期為準，按下列約定，給付「癌症（重度）特定粒子精準放射治療保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三倍。「癌症（重度）特定粒子精準放射治療保險金」最多以給付一次為限。第十八條實體癌症第四期自體免疫細胞治療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「實體癌第四期」，且接受「自體免疫細胞治療」者，本公司以療程中實際接受培養之自體免疫細胞第一針（劑）注射日期為準，按下列約定，給付「實體癌症第四期自體免疫細胞治療保險金」：一、第一保險單年度以內：「保險金額」。二、第二保險單年度（含）以後：「保險金額」'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 7, '實體癌症第四期自體免疫細胞治療', '實體癌症第四期自體免疫細胞治療保險金', '第2年起：保額 × 10（第1年內：保額 × 1）', '第十八條實體癌症第四期自體免疫細胞治療保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」及「實體癌第四期」，且接受「自體免疫細胞治療」者，本公司以療程中實際接受培養之自體免疫細胞第一針（劑）注射日期為準，按下列約定，給付「實體癌症第四期自體免疫細胞治療保險金」：一、第一保險單年度以內：「保險金額」。二、第二保險單年度（含）以後：「保險金額」的十倍。「實體癌症第四期自體免疫細胞治療保險金」最多以給付一次為限。第十九條白血病造血幹細胞移植保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，且因白血病於醫院住院接受「造血幹細胞移植」者，本公司以首次接受移植之日期為準，按下列約定，給付「白血病造血幹細胞移植保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三倍。「白血病造血幹細胞移植保險金」最多以給付一次為限。'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 8, '白血病造血幹細胞移植', '白血病造血幹細胞移植保險金', '第2年起：保額 × 3（第1年內：保額 × 30%）', '第十九條白血病造血幹細胞移植保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，且因白血病於醫院住院接受「造血幹細胞移植」者，本公司以首次接受移植之日期為準，按下列約定，給付「白血病造血幹細胞移植保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三倍。「白血病造血幹細胞移植保險金」最多以給付一次為限。被保險人接受第一項首次移植之日期已逾本契約有效期間，但移植當次住院始日於本契約有效期間內，本公司仍依本條之約定給付「白血病造血幹細胞移植保險金」。第二十條惡性淋巴瘤造血幹細胞移植保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，且因惡性淋巴瘤於醫院住院接受「造血幹細胞移植」者，本公司以首次接受移植之日期為準，按下列約定，給付「惡性淋巴瘤造血幹細胞移植'),
  ('cathay', '國泰人壽精準康愛防癌定期健康保險（外溢型）', 9, '惡性淋巴瘤造血幹細胞移植', '惡性淋巴瘤造血幹細胞移植保險金', '第2年起：保額 × 3（第1年內：保額 × 30%）', '第二十條惡性淋巴瘤造血幹細胞移植保險金的給付被保險人於本契約有效期間內，符合「診斷確定罹患癌症」，且因惡性淋巴瘤於醫院住院接受「造血幹細胞移植」者，本公司以首次接受移植之日期為準，按下列約定，給付「惡性淋巴瘤造血幹細胞移植保險金」：一、第一保險單年度以內：「保險金額」的百分之三十。二、第二保險單年度（含）以後：「保險金額」的三倍。「惡性淋巴瘤造血幹細胞移植保險金」最多以給付一次為限。被保險人接受第一項首次移植之日期已逾本契約有效期間，但移植當次住院始日於本契約有效期間內，本公司仍依本條之約定給付「惡性淋巴瘤造血幹細胞移植保險金」。第二十一條健康促進保險費折減本契約有效期間內，實際年齡達十八歲（含）以上之被保險人使用本公司指定之程式並加入指定之健康計劃，於「指定日期」之會員等級符合下表所定標準之一者，本公司按該表所列折減比例，折減本契約（不含'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 1, '滿期', '滿期保險金', '依已繳保費計算（看原文）', '十六、「月繳保險費年化總額」：指以「月繳應繳保險費」的十二倍乘上下列期日所對應之保險單年度所計得之金額：（一）給付「滿期保險金」時：原定繳費期間屆滿日。'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 2, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 20%（第1年內：保費 × 1）', '第十四條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之二十。本契約因第十條或第十二條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十五條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 3, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '分情況（看原文）', '第十五條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「月繳保險費年化總額」的一點三倍。'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 4, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第十八條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故，且未曾符合得申領「初次罹患癌症（重度）保險金」者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 5, '癌症（重度）追蹤照護', '癌症（重度）追蹤照護保險金', '保額 × 10%', '第十六條癌症（重度）追蹤照護保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，自診斷確定日的次一保險單週年日起，每逢各保險單週年日（含保險期間屆滿日）仍生存者，本公司按「保險金額」的百分之十，給付「癌症（重度）追蹤照護保險金」。'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 6, '癌症（重度）標靶藥物治療補助', '癌症（重度）標靶藥物治療補助保險金', '保額 × 10%', '第十七條癌症（重度）標靶藥物治療補助保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「診斷確定罹患癌症」及「癌症（重度）」，且於醫院實際注射或口服「標靶治療藥物」接受「標靶治療」者，本公司按「保險金額」的百分之十，給付「癌症（重度）標靶藥物治療補助保險金」。'),
  ('cathay', '國泰人壽鑫溢滿滿防癌定期保險（外溢型）', 7, '完全失能', '完全失能保險金', '保額 × 1', '第十九條完全失能保險金的給付被保險人於本契約有效期間內致成附表一所列完全失能程度之一，且未曾符合得申領「初次罹患癌症（重度）保險金」者，本公司按「當年度保險金額」給付「完全失能保險金」。'),
  ('cathay', '國泰人壽樂鍾心特定傷病定期健康保險（外溢型）', 1, '生活補助', '生活補助保險金', '保額 × 36%', '第十三條生活補助保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內初次診斷確定罹患特定傷病，自初次診斷確定罹患特定傷病的次一個保險單週年日起，每逢各保險單週年日仍生存者，本公司按「保險金額」的百分之三十六，給付「生活補助保險金」。'),
  ('cathay', '國泰人壽樂鍾心特定傷病定期健康保險（外溢型）', 2, '特定傷病', '特定傷病保險金', NULL, '第十二條特定傷病保險金的給付被保險人於本契約等待期間屆滿翌日或復效日起的有效期間內，經初次診斷確定罹患特定傷病時，本公司按初次診斷確定罹患特定傷病之日，下列二款方式計算之金額給付「特定傷病保險金」：一、診斷確定日於第一保險單年度以內：「年繳應繳保險費」的一點零二倍。'),
  ('cathay', '國泰人壽樂鍾心特定傷病定期健康保險（外溢型）', 3, '無理賠回饋', '無理賠回饋保險金', '依已繳保費計算（看原文）', '第十四條無理賠回饋保險金的給付被保險人於本契約有效期間內，未曾因罹患特定傷病而申領「特定傷病保險金」，且每逢保險單年度末仍生存者，本公司按「每單位年繳應繳保險費」的百分之十（元以下無條件進位）乘以「單位數」所得之金額，給付「無理賠回饋保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 1, '祝壽', '祝壽保險金', '保額 × 1', '第二十三條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 2, '身故', '身故保險金', '保額 × 1', '第二十四條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 3, '住院日額', '住院日額保險金', '日額 × 天數', '第十二條住院日額保險金的給付被保險人於本契約有效期間內，因疾病或傷害而於醫院接受住院診療者，本公司按「住院醫療保險金日額」乘以被保險人「住院日數」，給付「住院日額保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 4, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', '日額 × 3 × 天數', '第十三條加護病房或燒燙傷病房保險金的給付被保險人於本契約有效期間內，因疾病或傷害而入住醫院之加護病房或燒燙傷病房接受治療者，除「住院日額保險金」外，本公司另按「住院醫療保險金日額」的三倍乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日），給付「加護病房或燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 5, '住院手術醫療', '住院手術醫療保險金', '日額 × 附表倍數', '第十四條住院手術醫療保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」乘以該手術項目之住院手術給付倍數，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 6, '住院手術看護', '住院手術看護保險金', '日額 × 3', '第十五條住院手術看護保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」的三倍，給付「住院手術看護保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 7, '門診手術醫療', '門診手術醫療保險金', '日額 × 3', '第十六條門診手術醫療保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」的三倍給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 8, '特定處置', '特定處置保險金', '日額 × 2', '第十七條特定處置保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所接受附表二的特定處置治療且已實際接受處置者，本公司按「住院醫療保險金日額」的二倍，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 9, '意外創傷縫合處置', '意外創傷縫合處置保險金', NULL, '第十八條意外創傷縫合處置保險金的給付被保險人於本契約有效期間內，因意外傷害事故於醫院或診所接受意外創傷縫合處置治療者，本公司按「住院醫療保險金日額」，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 10, '醫材補助', '醫材補助保險金', '日額 × 10', '第十九條醫材補助保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須且已實際於醫院或診所接受下列治療之一者，本公司按「住院醫療保險金日額」的十倍，給付「醫材補助保險金」：一、人工水晶體植入術。'),
  ('cathay', '國泰人壽享醫靠醫療終身保險', 11, '未住院無理賠回饋', '未住院無理賠回饋保險金', '依已繳保費計算（看原文）', '第二十條未住院無理賠回饋保險金的給付被保險人於本契約有效期間內，每逢保險單年度末仍生存，且於該保險單年度內未曾因疾病或傷害於醫院接受住院診療而申領第十二條、第十三條、第十四條或第十五條之保險金時，本公司按「月繳應繳保險費」，給付「未住院無理賠回饋保險金」。'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 1, '滿期', '滿期保險金', '保額 × 1', '第十一條滿期保險金的給付被保險人於本契約有效期間且保險年齡到達九十歲之保險單週年日時仍生存者，本公司按「當年度保險金額」給付「滿期保險金」。'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 2, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 10%（第1年內：保費 × 1.06）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之十。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 3, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 1（第1年內：保費 × 1.06）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」。被保險人如先符合「初次診斷確定罹患癌症（重度）」後符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」或同時符合前述二者，本公司僅給付「初次罹患癌症（重度）保險金」。「初次罹患癌症（重度）保險金」最多以給付一次為限。第十四條特定癌症（重度）保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 4, '特定癌症（重度）', '特定癌症（重度）保險金', '第6年起：保額 × 50%（第2年：保額 × 10%；第3年：保額 × 20%；第4年：保額 × 30%；第5年：保額 × 40%）', '第十四條特定癌症（重度）保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」時其罹患之癌症屬附表一之「特定癌症（重度）」者，本公司按下列約定之一，給付「特定癌症（重度）保險金」：一、診斷確定日在第二保險單年度：「保險金額」的百分之十。二、診斷確定日在第三保險單年度：「保險金額」的百分之二十。三、診斷確定日在第四保險單年度：「保險金額」的百分之三十。四、診斷確定日在第五保險單年度：「保險金額」的百分之四十。五、診斷確定日在第六保險單年度（含）以後：「保險金額」的百分之五十。被保險人如符合「初次診斷確定罹患癌症（重度）」時其罹患之癌症不屬「特定癌症（重度）」者，本公司不再給付「特定癌症（重度）保險金」。「特定癌症（重度）保險金」最多以給付一次為限。第十五條骨折保險金的給付被保險人於本契約有效'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 5, '骨折', '骨折保險金', '保額 × 附表比例', '第十五條骨折保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院、診所（不含國術館、接骨所）診斷致成附表二骨折別表所列骨折項目之一（含不完全骨折及骨骼龜裂）者，本公司按「保險金額」的百分之十，乘以附表二骨折別表所定給付比例，給付「骨折保險金」。'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 6, '特定手術', '特定手術保險金', '保額 × 2%', '第十六條特定手術保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表三的特定手術治療且已實際接受特定手術者，本公司以「保險金額」的百分之二給付「特定手術保險金」。'),
  ('cathay', '國泰人壽好康愛防癌定期保險（外溢型）', 7, '身故', '身故保險金', '保額 × 1', '第十七條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽安心守護A型長期照顧終身保險（外溢型）（實物給付型保險商品）', 1, '完全失能生活扶助', '完全失能生活扶助保險金', '保額 × 12', '全失能生活扶助保險金的給付被保險人於本契約有效期間內，經醫師診斷確定符合附表二所列完全失能程度之一者，本公司以失能診斷確定日之保險金額乘以十二，給付第一次「完全失能生活扶助保險金」，並自失能診斷確定日起每屆滿一年之日，被保險人仍生存時，本公司按保險金額乘以十二，給付第二次（含）以後之「完全失能生活扶助保險金」，惟本公司給付「完全失能生活扶助保險金」之次數以十六次為最高給付次數上限。'),
  ('cathay', '國泰人壽安心守護A型長期照顧終身保險（外溢型）（實物給付型保險商品）', 2, '長期照顧復健', '長期照顧復健保險金', '保額 × 12', '第十一條長期照顧復健保險金的給付被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿之翌日，按「保險金額」乘以十二，給付「長期照顧復健保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽安心守護A型長期照顧終身保險（外溢型）（實物給付型保險商品）', 3, '完全失能關懷', '完全失能關懷保險金', '保額 × 12', '第十五條完全失能關懷保險金的給付被保險人於本契約有效期間內，經醫師診斷確定符合附表二所列完全失能程度之一者，本公司以失能診斷確定日之保險金額乘以十二，給付「完全失能關懷保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽安心守護B型長期照顧終身健康保險（外溢型）（實物給付型保險商品）', 1, '完全失能生活扶助', '完全失能生活扶助保險金', '保額 × 12', '全失能生活扶助保險金的給付被保險人於本契約有效期間內，經醫師診斷確定符合附表二所列完全失能程度之一者，本公司以失能診斷確定日之保險金額乘以十二，給付第一次「完全失能生活扶助保險金」，並自失能診斷確定日起每屆滿一年之日，被保險人仍生存時，本公司按保險金額乘以十二，給付第二次（含）以後之「完全失能生活扶助保險金」，惟本公司給付「完全失能生活扶助保險金」之次數以十六次為最高給付次數上限。'),
  ('cathay', '國泰人壽安心守護B型長期照顧終身健康保險（外溢型）（實物給付型保險商品）', 2, '長期照顧復健', '長期照顧復健保險金', '保額 × 12', '第十一條長期照顧復健保險金的給付被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿之翌日，按「保險金額」乘以十二，給付「長期照顧復健保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽安心守護B型長期照顧終身健康保險（外溢型）（實物給付型保險商品）', 3, '完全失能關懷', '完全失能關懷保險金', '保額 × 12', '第十五條完全失能關懷保險金的給付被保險人於本契約有效期間內，經醫師診斷確定符合附表二所列完全失能程度之一者，本公司以失能診斷確定日之保險金額乘以十二，給付「完全失能關懷保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 1, '滿期', '滿期保險金', '保額 × 1', '第十一條滿期保險金的給付被保險人於本契約有效期間且保險年齡到達九十歲之保險單週年日時仍生存者，本公司按「當年度保險金額」給付「滿期保險金」。'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 2, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 10%（第1年內：保費 × 1.06）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」的百分之十。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 3, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 1（第1年內：保費 × 1.06）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」。被保險人如先符合「初次診斷確定罹患癌症（重度）」後符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」或同時符合前述二者，本公司僅給付「初次罹患癌症（重度）保險金」。「初次罹患癌症（重度）保險金」最多以給付一次為限。第十四條特定癌症（重度）保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 4, '特定癌症（重度）', '特定癌症（重度）保險金', '第6年起：保額 × 50%（第2年：保額 × 10%；第3年：保額 × 20%；第4年：保額 × 30%；第5年：保額 × 40%）', '第十四條特定癌症（重度）保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」時其罹患之癌症屬附表一之「特定癌症（重度）」者，本公司按下列約定之一，給付「特定癌症（重度）保險金」：一、診斷確定日在第二保險單年度：「保險金額」的百分之十。二、診斷確定日在第三保險單年度：「保險金額」的百分之二十。三、診斷確定日在第四保險單年度：「保險金額」的百分之三十。四、診斷確定日在第五保險單年度：「保險金額」的百分之四十。五、診斷確定日在第六保險單年度（含）以後：「保險金額」的百分之五十。被保險人如符合「初次診斷確定罹患癌症（重度）」時其罹患之癌症不屬「特定癌症（重度）」者，本公司不再給付「特定癌症（重度）保險金」。「特定癌症（重度）保險金」最多以給付一次為限。第十五條骨折保險金的給付被保險人於本契約有效'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 5, '骨折', '骨折保險金', '保額 × 附表比例', '第十五條骨折保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院、診所（不含國術館、接骨所）診斷致成附表二骨折別表所列骨折項目之一（含不完全骨折及骨骼龜裂）者，本公司按「保險金額」的百分之十，乘以附表二骨折別表所定給付比例，給付「骨折保險金」。'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 6, '特定手術', '特定手術保險金', '保額 × 2%', '第十六條特定手術保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表三的特定手術治療且已實際接受特定手術者，本公司以「保險金額」的百分之二給付「特定手術保險金」。'),
  ('cathay', '國泰人壽豪康愛防癌定期保險（外溢型）', 7, '身故', '身故保險金', '保額 × 1', '第十七條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 1, '祝壽', '祝壽保險金', '保額 × 1', '第二十條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達九十九歲之保險單週年日仍生存時，本公司按「當年度保險金額」給付「祝壽保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 2, '身故', '身故保險金', '保額 × 1', '第二十一條所繳保險費的退還、身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 3, '住院手術醫療', '住院手術醫療保險金', NULL, '第十一條住院手術醫療保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「保險金額」，乘以手術日當年度之「增額係數」，再乘以該手術項目於附表一的「手術等級」所相對應的「手術保險金倍數」後計得之金額，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 4, '住院手術療養', '住院手術療養保險金', '保額 × 5', '第十二條住院手術療養保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「保險金額」乘以五後計得之金額，給付「住院手術療養保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 5, '重大手術慰問', '重大手術慰問保險金', '保額 × 2', '保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所接受手術治療且已實際接受手術者，如該手術項目於附表一的「手術等級」為第九級（含）以上者，除「住院手術醫療保險金」或「門診手術醫療保險金」外，本公司另按「保險金額」乘以二分之一，再乘以該手術項目於附表一的「手術等級」所相對應的「手術保險金倍數」後計得之金額，給付「重大手術慰問保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 6, '門診手術醫療', '門診手術醫療保險金', NULL, '第十四條門診手術醫療保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按「保險金額」，乘以手術日當年度之「增額係數」，再乘以該手術項目於附表一的「手術等級」所相對應的「手術保險金倍數」後計得之金額，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 7, '特定處置', '特定處置保險金', '保額 × 附表比例（再乘增額係數）', '第十五條特定處置保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所接受附表二的特定處置治療且已實際接受處置者，本公司按「保險金額」，乘以特定處置日當年度之「增額係數」，再乘以該特定處置項目於附表二所相對應的「特定處置給付倍數」後計得之金額，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 8, '意外創傷縫合處置', '意外創傷縫合處置保險金', '保額 × 1.5（再乘增額係數）', '第十六條意外創傷縫合處置保險金的給付被保險人於本契約有效期間內，因意外傷害經醫師診斷必須於醫院或診所接受意外創傷縫合處置治療且已實際接受處置者，本公司按「保險金額」乘以一點五，再乘以意外創傷縫合處置日當年度之「增額係數」，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽醫定安心手術醫療終身保險', 9, '醫材補助', '醫材補助保險金', '保額 × 25', '第十七條醫材補助保險金的給付被保險人於本契約有效期間內，因疾病或傷害經醫師診斷必須且已實際於醫院或診所接受下列治療之一者，本公司按「保險金額」，乘以二十五後計得之金額，給付「醫材補助保險金」：編號醫材補助項目1人工水晶體植入術。'),
  ('cathay', '國泰人壽醫護康愛防癌定期健康保險（外溢型）', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '第2年起：保額 × 5（第1年內：保費 × 1.06）', '第十二條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」乘以五。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日'),
  ('cathay', '國泰人壽醫護康愛防癌定期健康保險（外溢型）', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '第2年起：保額 × 12（第1年內：保費 × 1.06）', '第十三條初次罹患癌症（重度）保險金的給付被保險人於本契約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在第一保險單年度以內：「年繳應繳保險費」乘以一點零六。二、診斷確定日在第二保險單年度（含）以後：「保險金額」乘以十二。被保險人如先符合「初次診斷確定罹患癌症（重度）」後符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」或同時符合前述二者，本公司僅給付「初次罹患癌症（重度）保險金」。「初次罹患癌症（重度）保險金」最多以給付一次為限。第十四條癌症（重度）照護保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）'),
  ('cathay', '國泰人壽醫護康愛防癌定期健康保險（外溢型）', 3, '癌症（重度）照護', '癌症（重度）照護保險金', '保額 × 12', '第十四條癌症（重度）照護保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」者，於「癌症（重度）照護期間」之每一「罹病週年日」仍生存者，本公司按「保險金額」乘以十二，給付「癌症（重度）照護保險金」。'),
  ('cathay', '國泰人壽醫護康愛防癌定期健康保險（外溢型）', 4, '癌症（重度）標靶藥物治療補助', '癌症（重度）標靶藥物治療補助保險金', '保額 × 12', '第十五條癌症（重度）標靶藥物治療補助保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」，且於醫院實際注射或口服「標靶治療藥物」接受「標靶治療」者，本公司按「保險金額」乘以十二，給付「癌症（重度）標靶藥物治療補助保險金」。'),
  ('cathay', '國泰人壽醫護康愛防癌定期健康保險（外溢型）', 5, '癌症（重度）營養補助', '癌症（重度）營養補助保險金', '保額 × 3', '第十六條癌症（重度）營養補助保險金的給付（第二保險單年度起適用）被保險人於本契約第二保險單年度（含）以後的有效期間內，符合「初次診斷確定罹患癌症（重度）」，於「癌症（重度）營養補助期間」之每一「罹病週年日」仍生存者，本公司按「保險金額」乘以三，給付「癌症（重度）營養補助保險金」。'),
  ('cathay', '國泰人壽睛彩萬分手術醫療定期健康保險', 1, '住院手術醫療', '住院手術醫療保險金', '保額 × 1', '第十二條住院手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受手術治療且已實際接受手術者，本公司按「保險金額」，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽睛彩萬分手術醫療定期健康保險', 2, '門診手術醫療', '門診手術醫療保險金', '保額 × 30%', '第十三條門診手術醫療保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受手術治療且已實際接受手術者，本公司按「保險金額」的百分之三十，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽睛彩萬分手術醫療定期健康保險', 3, '特定處置', '特定處置保險金', '保額 × 30%', '第十四條特定處置保險金的給付被保險人於本契約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表一所列之特定處置項目治療且已實際接受處置者，本公司按「保險金額」的百分之三十，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽睛彩萬分手術醫療定期健康保險', 4, '眼睛醫療', '眼睛醫療保險金', '保額 × 2', '第十五條眼睛醫療保險金的給付被保險人於本契約有效期間內因眼睛之疾病或傷害，符合下列情事之一者，本公司按本契約保險單上所記載之「保險金額」乘以二，給付「眼睛醫療保險金」:一、經醫師診斷必須於醫院或診所接受附表二的手術治療，且實際已接受手術者。'),
  ('cathay', '國泰人壽睛彩萬分手術醫療定期健康保險', 5, '雙目失明', '雙目失明保險金', '保額 × 15', '第十六條雙目失明保險金的給付被保險人於本契約有效期間內，因疾病或傷害，致成第二條約定之「雙目失明」者，本公司按「保險金額」乘以十五，給付「雙目失明保險金」。'),
  ('cathay', '國泰人壽宅心安一年定期住院日額暨在宅急症照護醫療健康保險', 1, '住院日額', '住院日額保險金', '日額 × 天數', '第十二條住院日額保險金的給付被保險人於本契約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按「住院醫療保險金日額」乘以「住院日數」，給付「住院日額保險金」。'),
  ('cathay', '國泰人壽宅心安一年定期住院日額暨在宅急症照護醫療健康保險', 2, '在宅急症照護日額', '在宅急症照護日額保險金', '日額 × 天數', '第十三條在宅急症照護日額保險金的給付被保險人於本契約有效期間內因疾病或傷害，而接受「在宅急症照護」者，本公司按「住院醫療保險金日額」乘以「在宅急症照護日數」，給付「在宅急症照護日額保險金」。'),
  ('cathay', '國泰人壽真永健PLUS住院日額健康保險附約（外溢型）', 1, '住院日額醫療', '住院日額醫療保險金', '日額 × 天數', '第十二條住院日額醫療保險金被保險人於本附約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按下列約定給付「住院日額醫療保險金」：一、被保險人同一次住院診療在三十日(含)以內者，本公司按保險單上所記載之「住院醫療保險金日額」乘以被保險人住院日數，給付「住院日額醫療保險金」。'),
  ('cathay', '國泰人壽真永健PLUS住院日額健康保險附約（外溢型）', 2, '出院療養', '出院療養保險金', '日額 × 50% × 天數', '第十三條出院療養保險金被保險人於本附約有效期間內因疾病或傷害，而於醫院接受住院診療者，除住院日額醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」的百分之五十乘以住院日數，給付「出院療養保險金」。'),
  ('cathay', '國泰人壽真永健PLUS住院日額健康保險附約（外溢型）', 3, '重大疾病住院日額醫療', '重大疾病住院日額醫療保險金', '日額 × 50% × 天數', '第十四條重大疾病住院日額醫療保險金被保險人於本附約有效期間內於醫院住院，且經醫師診斷確定罹患重大疾病並實施診療者，除住院日額醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」的百分之五十乘以被保險人住院日數給付「重大疾病住院日額醫療保險金」。'),
  ('cathay', '國泰人壽真永健PLUS住院日額健康保險附約（外溢型）', 4, '加護病房及燒燙傷病房', '加護病房及燒燙傷病房保險金', '日額 × 2 × 天數', '第十五條加護病房及燒燙傷病房保險金被保險人於本附約有效期間內因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受診療者，除住院日額醫療保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」的二倍乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日，但如轉入與轉出為同一日，該日不得重複計入），給付「加護病房及燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽鍾溢祝福重大疾病健康保險附約(乙型)(外溢型)', 1, '輕度重大疾病', '輕度重大疾病保險金', '續保後：保額 × 20%（第1年內：保額 × 10%）', '第十一條輕度重大疾病保險金的給付被保險人於本附約等待期間屆滿翌日、續保日或復效日起的有效期間內，經醫院醫師初次診斷罹患「輕度重大疾病」者，本公司按下列約定之一，給付「輕度重大疾病保險金」：一、診斷確定日在本附約投保（或附加）後之第一保險單年度以內：保險金額的百分之十。二、診斷確定日於續保年度：保險金額的百分之二十。被保險人同時或先後罹患二項以上「輕度重大疾病」時，本公司僅給付一項「輕度重大疾病保險金」。「輕度重大疾病保險金」終身最多以給付一次為限。第十二條重大疾病保險金的給付被保險人於本附約等待期間屆滿翌日、續保日或復效日起的有效期間內，經醫院醫師初次診斷罹患「重大疾病」者，本公司按下列約定之一，給付「重大疾病保險金」，但被保險人於續保前或本附約有效期間內曾得申領第十一條「輕度重大疾病保險金」者，'),
  ('cathay', '國泰人壽鍾溢祝福重大疾病健康保險附約(乙型)(外溢型)', 2, '重大疾病', '重大疾病保險金', '續保後：保額 × 1.3（第1年內：保額 × 20%）', '第十二條重大疾病保險金的給付被保險人於本附約等待期間屆滿翌日、續保日或復效日起的有效期間內，經醫院醫師初次診斷罹患「重大疾病」者，本公司按下列約定之一，給付「重大疾病保險金」，但被保險人於續保前或本附約有效期間內曾得申領第十一條「輕度重大疾病保險金」者，應扣除之：一、診斷確定日在本附約投保（或附加）後之第一保險單年度以內：保險金額的百分之二十。二、診斷確定日於續保年度：保險金額的一點三倍。被保險人同時或先後罹患二項以上「重大疾病」時，本公司僅給付一項「重大疾病保險金」。「重大疾病保險金」終身最多以給付一次為限。第十三條健康促進保險費折減本附約實際年齡達十八歲（含）以上之被保險人使用本公司指定之程式並加入指定之健康計劃，於「指定日期」之會員等級符合下表所定標準之一者，本公司按該表所列折減'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 1, '傷害醫療日額', '傷害醫療日額保險金', '日額 × 天數', '第二條傷害醫療日額保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院治療者，本公司按本附約保險單上所記載之「傷害醫療保險金日額」乘以實際住院日數給付「傷害醫療日額保險金」；'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 2, '燒燙傷、加護病房', '燒燙傷、加護病房保險金', '日額 × 2 × 天數', '第三條燒燙傷、加護病房保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，因此蒙受燒燙傷或其他意外傷害，於醫院燒燙傷或加護病房接受治療者，本公司將按本附約保險單上所記載之「傷害醫療保險金日額」的二倍乘以實際住進燒燙傷病房或加護病房之日數，給付「燒燙傷、加護病房保險金」。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 3, '出院療養', '出院療養保險金', NULL, '第四條出院療養保險金的給付被保險人於本附加條款有效期間內遭受本附約第二條約定的意外傷害事故，並於醫院住院後出院療養者，本公司按本附約保險單上所記載之「傷害醫療保險金日額」的二分之一乘以實際住院日數，給付「出院療養保險金」。'),
  ('cathay', '國泰人壽超全方位傷害暨兒童傷害失能保險附約', 4, '住院生活補助', '住院生活補助保險金', '日額 × 天數', '２.自第三十一日起，本公司按本附約保險單上所記載之「傷害醫療保險金日額」乘以實際超過三十日以上之住院日數，給付「住院生活補助保險金」。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 1, '意外身故', '意外事故身故保險金', '保額 × 1', '第十一條意外事故身故或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故，且其身故時之保險年齡滿十六歲者，本公司按本附約保險單上所記載之保險金額給付意外事故身故保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 2, '身故', '喪葬費用保險金', NULL, '第二十一條失蹤處理被保險人在本附約有效期間內因意外傷害事故失蹤，於戶籍資料所載失蹤之日起滿一年仍未尋獲，或要保人、受益人能提出證明文件足以認為被保險人極可能因本附約所約定之意外傷害事故而身故者，本公司按第十一條至第十三條約定先行給付身故或喪葬費用保險金，但日後發現被保險人生還時，要保人或受益人應將該筆已領之退還已繳保險費或身故或喪葬費用保險金歸還本公司，其間有應繳而未繳之保險費者，於要保人一次清償後，本附約自'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 3, '意外事故身故或喪葬費用', '意外事故身故或喪葬費用保險金', NULL, '第十二條水陸交通意外事故身故或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的水陸交通意外事故，自該水陸交通意外事故發生之日起一百八十日以內身故，且其身故時之保險年齡滿十六歲者，本公司除依第十一條約定給付意外事故身故或喪葬費用保險金外，另按本附約保險單上所記載之保險金額的二倍，給付水陸交通意外事故身故或喪葬費用保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 4, '水陸交通意外事故身故或喪葬費用', '水陸交通意外事故身故或喪葬費用保險金', '保額 × 2', '第十二條水陸交通意外事故身故或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的水陸交通意外事故，自該水陸交通意外事故發生之日起一百八十日以內身故，且其身故時之保險年齡滿十六歲者，本公司除依第十一條約定給付意外事故身故或喪葬費用保險金外，另按本附約保險單上所記載之保險金額的二倍，給付水陸交通意外事故身故或喪葬費用保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 5, '火災意外事故身故或喪葬費用', '火災意外事故身故或喪葬費用保險金', '保額 × 1', '第十三條火災意外事故身故或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的火災意外事故，自火災意外事故發生之日起一百八十日以內身故，且其身故時之保險年齡滿十六歲者，本公司除依第十一條約定給付意外事故身故或喪葬費用保險金外，另按本附約保險單上所記載之保險金額，給付火災意外事故身故或喪葬費用保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 6, '意外事故失能', '意外事故失能保險金', '保額 × 附表比例', '第十四條意外事故失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表三所列失能程度之一，且其失能時之保險年齡滿十六歲者，本公司按本附約保險單上所記載之保險金額為準，依附表三所列比例計算給付意外事故失能保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 7, '水陸交通意外事故第一級失能', '水陸交通意外事故第一級失能保險金', '保額 × 2', '第十五條水陸交通意外事故第一級失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的水陸交通意外事故，自該水陸交通意外事故發生之日起一百八十日以內致成附表三所列第一級失能項目之一，且其失能時之保險年齡滿十六歲者，本公司除依第十四條約定給付意外事故失能保險金外，另按本附約保險單上所記載之保險金額的二倍，給付水陸交通意外事故第一級失能保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 8, '火災意外事故第一級失能', '火災意外事故第一級失能保險金', '保額 × 1', '第十六條火災意外事故第一級失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的火災意外事故，自火災意外事故發生之日起一百八十日以內致成附表三所列第一級失能項目之一，且其失能時之保險年齡滿十六歲者，本公司除依第十四條約定給付意外事故失能保險金外，另按本附約保險單上所記載之保險金額，給付火災意外事故第一級失能保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 9, '意外骨折', '意外骨折保險金', '保額 × 附表比例', '第十八條意外骨折保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內，經登記合格的醫院、診所(不含國術館、接骨所)診斷致成附表一骨折別表所列骨折項目之一者，本公司按本附約保險單上所記載之保險金額乘以骨折別表所定給付比例，給付意外骨折保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 10, '一次意外骨折', '一次意外骨折保險金', NULL, '同一意外傷害事故僅給付一次意外骨折保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 11, '百分比核付意外骨折', '百分比核付意外骨折保險金', NULL, '若被保險人因意外傷害事故所致之骨折非屬骨折別表所列之骨折項目時，由本公司與被保險人協議給付百分比核付意外骨折保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 12, '意外脫臼手術', '意外脫臼手術保險金', '保額 × 附表比例', '第十九條意外脫臼手術保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故致成附表二脫臼別表所列脫臼項目之一，自意外傷害事故發生之日起一百八十日以內經醫師診斷必須且實際施行「脫臼開放性復位術」治療者，本公司按本附約保險單上所記載之保險金額乘以脫臼別表所定給付比例，給付意外脫臼手術保險金。'),
  ('cathay', '國泰人壽新金骨力傷害暨兒童意外骨折保險附約', 13, '一次意外脫臼手術', '一次意外脫臼手術保險金', NULL, '被保險人因同一意外傷害事故致成二項以上脫臼經醫師診斷必須且實際施行二項以上之「脫臼開放性復位術」治療者，本公司僅給付一項較高比例之意外脫臼手術保險金，且同一脫臼部位經醫師診斷必須且實際施行二項以上之「脫臼開放性復位術」治療者，本公司僅給付一次意外脫臼手術保險金。'),
  ('cathay', '國泰人壽享保障小額傷害保險附約', 1, '意外身故', '意外事故身故保險金', NULL, '第十二條意外事故身故保險金或喪葬費用保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按保險單上所記載本附約之保險金額給付意外事故身故保險金，本附約效力即行終止。'),
  ('cathay', '國泰人壽享保障小額傷害保險附約', 2, '身故', '喪葬費用保險金', NULL, '前項情形，如要保人向二家（含）以上保險公司投保，或向同一保險公司投保數個保險契（附）約，且其投保之喪葬費用保險金額合計超過所定之限額者，本公司於所承保之喪葬費用金額範圍內，依各要保書所載之要保時間先後，依約給付喪葬費用保險金至前項喪葬費用額度上限為止，如有二家以上保險公司之保險契約要保時間相同或無法區分其要保時間之先後者，各該保險公司應依其喪葬費用保險金額與扣除要保時間在先之保險公'),
  ('cathay', '國泰人壽享保障小額傷害保險附約', 3, '意外事故失能', '意外事故失能保險金', '保額 × 附表比例', '第十三條意外事故失能保險金的給付被保險人於本附約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按保險單上所記載本附約之保險金額為準，依附表所列比例計算給付意外事故失能保險金。'),
  ('cathay', '國泰人壽自由配一年定期初次罹患癌症健康保險附約（外溢型）', 1, '初次罹患癌症（初期）或癌症（輕度）', '初次罹患癌症（初期）或癌症（輕度）保險金', '續保後：保額 × 20%（第1年內：保額 × 2%）', '第十一條初次罹患癌症（初期）或癌症（輕度）保險金的給付被保險人於本附約有效期間內，符合「初次診斷確定罹患癌症（初期）或癌症（輕度）」者，本公司按下列約定之一，給付「初次罹患癌症（初期）或癌症（輕度）保險金」：一、診斷確定日在本附約投保(或附加)後之第一保險單年度以內：「保險金額」的百分之二。二、診斷確定日在續保年度：「保險金額」的百分之二十。本契約因第九條或第十條所列情形終止前，被保險人如已符合前項約定未提出申領者，本公司仍按前項約定給付之。「初次罹患癌症（初期）或癌症（輕度）保險金」最多以給付一次為限。第十二條初次罹患癌症（重度）保險金的給付被保險人於本附約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕'),
  ('cathay', '國泰人壽自由配一年定期初次罹患癌症健康保險附約（外溢型）', 2, '初次罹患癌症（重度）', '初次罹患癌症（重度）保險金', '分情況（看原文）', '第十二條初次罹患癌症（重度）保險金的給付被保險人於本附約有效期間內，符合「初次診斷確定罹患癌症（重度）」者，本公司按下列約定之一，給付「初次罹患癌症（重度）保險金」，但被保險人曾得申領「初次罹患癌症（初期）或癌症（輕度）保險金」者，應扣除之：一、診斷確定日在本附約投保(或附加)後之第一保險單年度以內：「保險金額」的百分之十'),
  ('cathay', '國泰人壽自由配一年定期健康保險附約（外溢型）', 1, '長期照顧復健', '長期照顧復健保險金', '保額 × 36', '第十一條長期照顧復健保險金的給付被保險人於本附約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿之翌日，按保險金額的三十六倍，給付「長期照顧復健保險金」，惟終身以領取一次為限。'),
  ('cathay', '國泰人壽自由配一年定期特定處置醫療健康保險附約（外溢型）', 1, '特定處置', '特定處置保險金', '保額 × 3', '第十一條特定處置保險金的給付被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表所列之特定處置項目治療且已實際接受處置者，本公司按「保險金額」三倍，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽睛彩人生PLUS手術醫療健康保險附約（外溢型）', 1, '眼睛醫療', '眼睛醫療保險金', '保額 × 1', '第十一條眼睛醫療保險金的給付被保險人於本附約有效期間內因眼睛之疾病或傷害，符合下列情事之一者，本公司按本附約保險單上所記載之「保險金額」，給付「眼睛醫療保險金」:一、經醫師診斷必須於醫院或診所接受附表一的手術治療，且實際已接受手術者。'),
  ('cathay', '國泰人壽心安PLUS手術醫療定期健康保險附約（外溢型）', 1, '住院手術醫療', '住院手術醫療保險金', '保額 × 附表倍數（再乘增額係數）', '第十一條住院手術醫療保險金的給付被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「保險金額」乘以手術日當年度之「增額係數」，再乘以手術給付倍數，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽心安PLUS手術醫療定期健康保險附約（外溢型）', 2, '門診手術醫療', '門診手術醫療保險金', '保額 × 附表倍數（再乘增額係數）', '第十二條門診手術醫療保險金的給付被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按「保險金額」乘以手術日當年度之「增額係數」，再乘以手術給付倍數，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽心安PLUS手術醫療定期健康保險附約（外溢型）', 3, '特定處置', '特定處置保險金', '保額 × 附表倍數（再乘增額係數）', '第十三條特定處置保險金的給付被保險人於本附約有效期間內因疾病或傷害，經醫師診斷必須於醫院或診所接受附表二所列之特定處置治療且已接受處置者，本公司按「保險金額」乘以特定處置日當年度之「增額係數」，再乘以特定處置給付倍數，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽心安PLUS手術醫療定期健康保險附約（外溢型）', 4, '意外創傷縫合處置', '意外創傷縫合處置保險金', '保額 × 附表倍數（再乘增額係數）', '第十四條意外創傷縫合處置保險金的給付被保險人於本附約有效期間內，因意外傷害事故，於醫院或診所接受附表三的意外創傷縫合處置治療者，本公司按「保險金額」乘以意外創傷縫合處置日當年度之「增額係數」，再乘以意外創傷縫合處置給付倍數，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 1, '住院日額', '住院日額保險金', '日額 × 天數', '第十二條住院日額保險金被保險人於本附約有效期間內因疾病或傷害，而於醫院接受住院診療者，本公司按下列約定給付「住院日額保險金」：一、被保險人同一次住院診療在三十日(含)以內者，本公司按保險單上所記載之「住院醫療保險金日額」乘以被保險人住院日數，給付「住院日額保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 2, '加護病房或燒燙傷病房', '加護病房或燒燙傷病房保險金', '日額 × 天數', '第十三條加護病房或燒燙傷病房保險金被保險人於本附約有效期間內因疾病或傷害，而於醫院之加護病房或燒燙傷病房接受診療者，除住院日額保險金外，本公司另按保險單上所記載之「住院醫療保險金日額」乘以二，再乘以實際住進加護病房或燒燙傷病房的日數（含轉入及轉出當日，但如轉入與轉出為同一日，該日不得重複計入），給付「加護病房或燒燙傷病房保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 3, '住院手術醫療', '住院手術醫療保險金', '日額 × 附表倍數', '第十四條住院手術醫療保險金被保險人於本附約有效期間內，因疾病或傷害經醫師診斷必須於醫院住院接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」，乘以該手術項目於附表一的「手術給付倍數」後計得之金額，給付「住院手術醫療保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 4, '門診手術醫療', '門診手術醫療保險金', '日額 × 附表倍數', '第十五條門診手術醫療保險金被保險人於本附約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所門診接受附表一的手術治療且已實際接受手術者，本公司按「住院醫療保險金日額」，乘以該手術項目於附表一的「手術給付倍數」後計得之金額，給付「門診手術醫療保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 5, '特定處置', '特定處置保險金', '日額 × 附表倍數', '第十六條特定處置保險金被保險人於本附約有效期間內，因疾病或傷害經醫師診斷必須於醫院或診所接受附表二的特定處置治療且已實際接受處置者，本公司按「住院醫療保險金日額」，乘以該特定處置項目於附表二所相對應的「特定處置給付倍數」後計得之金額，給付「特定處置保險金」。'),
  ('cathay', '國泰人壽新真大心PLUS住院醫療健康保險附約（外溢型）', 6, '意外創傷縫合處置', '意外創傷縫合處置保險金', '日額 × 附表倍數', '第十七條意外創傷縫合處置保險金被保險人於本附約有效期間內因意外傷害事故，於醫院或診所接受附表三的意外創傷縫合處置治療者，本公司按「住院醫療保險金日額」，乘以該意外創傷縫合處置項目於附表三所相對應的「意外創傷縫合處置給付倍數」後計得之金額，給付「意外創傷縫合處置保險金」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 1, '身故', '身故保險金', NULL, '第六條身故保險金的給付被保險人於本契約有效期間內遭受第三條約定的傷害事故，並於事故發生之日起一百八十日以內身故者，本公司按本契約保險單所記載的該被保險人的保險金額給付「身故保險金」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 2, '失能', '失能保險金', '保額 × 附表比例', '第七條失能保險金的給付被保險人於本契約有效期間內遭受第三條約定的傷害事故，並於事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按本契約保險單所記載該被保險人的保險金額為準，依該表所列比例給付「失能保險金」。'),
  ('cathay', '國泰人壽工地工程人員團體傷害保險', 3, '傷害醫療', '傷害醫療保險金', NULL, '附件附加醫療保險金條款（傷害醫療保險金）第一條傷害醫療保險金的給付被保險人於本契約有效之保險期間內遭受本契約第三條的傷害事故，並於醫院或診所接受治療者，本公司以本契約保險單所記載的該被保險人的「每次傷害醫療保險金限額」為限，按每次事故實際醫療費用給付「傷害醫療保險金」。'),
  ('cathay', '國泰人壽微型傷害保險', 1, '身故', '身故保險金', '保額 × 1', '第五條身故或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第四條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成死亡者，本公司按本契約保險單上所記載之保險金額給付身故保險金。'),
  ('cathay', '國泰人壽微型傷害保險', 2, '失能', '失能保險金', '保額 × 附表比例', '第六條失能保險金的給付被保險人於本契約有效期間內遭受第四條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按本契約保險單上所記載之保險金額為準，依附表所列比例計算給付失能保險金。'),
  ('cathay', '國泰人壽微型個人傷害保險', 1, '意外身故', '意外身故保險金', '保額 × 1', '第十條意外身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按本契約保險單上所記載之保險金額給付「意外身故保險金」，本契約效力即行終止。'),
  ('cathay', '國泰人壽微型個人傷害保險', 2, '意外失能', '意外失能保險金', '保額 × 附表比例', '第十一條意外失能保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按本契約保險單上所記載之保險金額為準，依附表所列比例計算給付「意外失能保險金」。'),
  ('cathay', '國泰人壽微型個人傷害保險', 3, '意外身故保險金或喪葬費用', '意外身故保險金或喪葬費用保險金', NULL, '第十八條失蹤處理被保險人在本契約有效期間內因第二條所約定的意外傷害事故失蹤，於戶籍資料所載失蹤之日起滿一年仍未尋獲，或要保人、受益人能提出證明文件足以認為被保險人極可能因本契約所約定之意外傷害事故而身故者，本公司按第十條約定先行給付「意外身故保險金或喪葬費用保險金」；'),
  ('cathay', '國泰人壽新iCarry傷害保險', 1, '身故', '喪葬費用保險金', NULL, '前述情形，如果要保人向2家（含）以上保險公司投保，或向同一保險公司投保數個保險契（附）約，且其投保的喪葬費用保險金額合計超過所定的限額時，本公司在所承保的喪葬費用金額範圍內，依各要保書所載要保時間先後，依約給付喪葬費用保險金至前述喪葬費用額度上限為止，如果有2家以上保險公司的保險契約要保時間相同或無法區分其要保時間先後時，各該保險公司應依其喪葬費用保險金額與扣除要保時間在先的保險公'),
  ('cathay', '國泰人壽新iCarry傷害保險', 2, '意外傷害事故失能', '意外傷害事故失能保險金', NULL, '被保險人因本次意外傷害事故所致之失能，如合併以前（含本契約訂立前）的失能，可領附表1所列較嚴重項目的意外傷害事故失能保險金者，本公司按較嚴重的項目給付意外傷害事故失能保險金，但以前的失能，視同依照本次給付條件已給付意外傷害事故失能保險金，應扣除之。'),
  ('cathay', '國泰人壽新iCarry傷害保險', 3, '條件已給付意外傷害事故失能', '條件已給付意外傷害事故失能保險金', NULL, '被保險人因本次意外傷害事故所致之失能，如合併以前（含本契約訂立前）的失能，可領附表1所列較嚴重項目的意外傷害事故失能保險金者，本公司按較嚴重的項目給付意外傷害事故失能保險金，但以前的失能，視同依照本次給付條件已給付意外傷害事故失能保險金，應扣除之。'),
  ('cathay', '國泰人壽新iCarry傷害保險', 4, '意外傷害事故身故', '意外傷害事故身故保險金', NULL, '第5條被保險人在本契約有效期間內因第2條所約定的意外傷害事故失蹤，於戶籍資料所載失蹤處理失蹤之日起滿１年仍未尋獲，或要保人、受益人能提出證明文件足以認為被保險人極可能因本契約所約定之意外傷害事故而身故者，本公司按第3條約定先行給付意外傷害事故身故保險金或喪葬費用保險金；'),
  ('cathay', '國泰人壽自由配一年定期意外身故與失能傷害保險', 1, '意外身故', '意外事故身故保險金', '保額 × 1', '第十條意外事故身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故，本公司按身故日之保險金額，給付意外事故身故保險金，本契約效力即行終止。'),
  ('cathay', '國泰人壽自由配一年定期意外身故與失能傷害保險', 2, '身故', '喪葬費用保險金', NULL, '前項情形，如要保人向二家（含）以上保險公司投保，或向同一保險公司投保數個保險契（附）約，且其投保之喪葬費用保險金額合計超過所定之限額者，本公司於所承保之喪葬費用金額範圍內，依各要保書所載之要保時間先後，依約給付喪葬費用保險金至前項喪葬費用額度上限為止，如有二家以上保險公司之保險契約要保時間相同或無法區分其要保時間之先後者，各該保險公司應依其喪葬費用保險金額與扣除要保時間在先之保險公'),
  ('cathay', '國泰人壽自由配一年定期意外身故與失能傷害保險', 3, '意外事故失能', '意外事故失能保險金', '保額 × 附表比例', '第十一條意外事故失能保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，本公司按失能診斷確定日之保險金額為準，依附表二所列比例計算，給付意外事故失能保險金。'),
  ('cathay', '國泰人壽意萬平安傷害暨兒童意外骨折定期保險', 1, '完全失能', '完全失能保險金', NULL, '四、本公司因第二十八條第三項約定未能給付「完全失能保險金」，而給付保單價值準備金。'),
  ('cathay', '國泰人壽意萬平安傷害暨兒童意外骨折定期保險', 2, '身故', '身故保險金或喪葬費用保險金', NULL, '因本條約定而未能給付「身故保險金或喪葬費用保險金」或「完全失能保險金」者，本契約累積達有保單價值準備金時，依照約定給付保單價值準備金予應得之人。'),
  ('cathay', '國泰人壽享保障微型個人傷害保險', 1, '意外身故', '意外身故保險金', '保額 × 1', '第十條意外身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按保險金額給付「意外身故保險金」。'),
  ('cathay', '國泰人壽享保障微型個人傷害保險', 2, '意外失能', '意外失能保險金', '保額 × 附表比例', '第十一條意外失能保險金的給付被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表所列失能程度之一者，本公司按保險金額為準，依附表所列比例計算給付「意外失能保險金」。'),
  ('cathay', '國泰人壽享保障微型個人傷害保險', 3, '意外身故保險金或喪葬費用', '意外身故保險金或喪葬費用保險金', NULL, '第十九條失蹤處理被保險人在本契約有效期間內因第二條所約定的意外傷害事故失蹤，於戶籍資料所載失蹤之日起滿一年仍未尋獲，或要保人、受益人能提出證明文件足以認為被保險人極可能因本契約所約定之意外傷害事故而身故者，本公司按第十條約定先行給付「意外身故保險金或喪葬費用保險金」；'),
  ('fubon', '富邦人壽全鑫如意保險', 1, '非意外傷害事故保險金或喪葬費用', '非意外傷害事故保險金或喪葬費用保險金', NULL, '第十二條被保險人在本契約有效期間內失蹤者，如經法院宣告死亡時，本公司根據判決內所確定死亡時日為準，依第十五條約定給付「非意外傷害事故保險金或喪葬費用保險金」；'),
  ('fubon', '富邦人壽全鑫如意保險', 2, '意外傷害身故保險金或喪葬費用', '意外傷害身故保險金或喪葬費用保險金', NULL, '如要保人或受益人能提出證明文件，足以認為被保險人極可能因意外傷害事故而死亡者，本公司應依意外傷害事故發生日為準，依第十四條約定給付「意外傷害身故保險金或喪葬費用保險金」。'),
  ('fubon', '富邦人壽全鑫如意保險', 3, '意外失能', '意外傷害失能保險金', '保額 × 附表比例', '被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列二至十一級失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，按保險金額乘以附表一所列二至十一級失能程度給付比例計算所得之金額給付「意外傷害失能保險金」。'),
  ('fubon', '富邦人壽全鑫如意保險', 4, '意外身故', '意外傷害身故保險金', NULL, '第十四條被保險人於本契約有效期間內遭受第二條約定的一般意外傷害事故或搭乘大眾運輸交通工具所發生之意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按下表約定給付「意外傷害身故保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽全鑫如意保險', 5, '非意外傷害事故', '非意外傷害事故保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間且於下列保單年度，非因意外傷害事故身故或致成附表二所列完全失能程度之一者，本公司按下列約定給付「非意外傷害事故保險金」後，本契約之效力即行終止：一、第一保單年度內，按身故或致成附表二所列完全失能程度之一時之當年度保險金額給付。'),
  ('fubon', '富邦人壽全鑫如意保險', 6, '滿期', '滿期保險金', '保額 × 1.06', '第十七條被保險人於本契約有效期間且保險期間屆滿時仍生存者，本公司按當年度保險金額的一點零六倍給付「滿期保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 1, '身故', '身故保險金或喪葬費用保險金', '分情況（看原文）', '第十九條被保險人於本契約有效期間內身故者，本公司按下列二者之最大值給付「身故保險金」後，本契約效力即行終止：一、當年度保險金額。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 2, '完全失能關懷', '完全失能關懷保險金', '保額 × 15', '第十四條被保險人於本契約有效期間內因第二條約定的疾病或意外傷害事故，經醫院醫師診斷確定符合附表二所列完全失能程度之一，且於完全失能診斷確定日仍生存者，本公司按完全失能診斷確定日當時之保險金額的十五倍給付「完全失能關懷保險金」，且本契約有效期間內以給付一次為限。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 3, '長期照顧一次', '長期照顧一次保險金', '保額 × 15', '第十六條被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司按免責期間屆滿時之保險金額的十五倍，給付「長期照顧一次保險金」，且本契約有效期間內以給付一次為限。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 4, '完全失能生活扶助', '完全失能生活扶助保險金', '保額 × 2', '第十五條被保險人於本契約有效期間內因第二條約定的疾病或意外傷害事故，經醫院醫師診斷確定致成附表二所列完全失能程度之一，且於完全失能診斷確定日仍生存者，本公司於完全失能診斷確定日起一年內之每一週月日（不論被保險人生存與否），按月依當時之保險金額的二倍乘以附表三累計給付年度對應之係數，依計算所得之金額給付「完全失能生活扶助保險金」。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 5, '長期照顧分期', '長期照顧分期保險金', '保額 × 2', '第十七條被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿翌日及一年內之每一週月日（不論被保險人生存與否），按月依當時之保險金額的二倍乘以附表三累計給付年度對應之係數，依計算所得之金額給付「長期照顧分期保險金」。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 6, '祝壽', '祝壽保險金', '保額 × 1', '第二十條被保險人於本契約有效期間內且保險年齡屆滿九十九歲仍生存者，本公司按當年度保險金額給付「祝壽保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十四條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 2, '特定重大傷病', '特定重大傷病保險金', '保額 × 20%', '十五條被保險人於本契約第二保單年度起之有效期間內，經醫院醫師診斷，確認首次罹患第二條約定之重大傷病之一，而得受領第十四條約定之「重大傷病保險金」，且該項重大傷病亦同時符合第二條約定之SDH11501227/31商品代號：SDH「特定重大傷病」者，本公司除給付「重大傷病保險金」外，另按罹患特定重大傷病時之保險金額的20％給付「特定重大傷病保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 3, '特定重大疾病', '特定重大疾病保險金', '取較高：保額 × 1／保費 × 1.06', '第十六條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定重大疾病項目之一者，本公司按下列二者之最大值給付「特定重大疾病保險金」後，本契約效力即行終止：一、罹患特定重大疾病時之保險金額。二、年繳保險費總和之一點零六倍。被保險人於本契約有效期間內，不論同時或先後罹患二項特定重大疾病，本公司僅對其中一項特定重大疾病負給付「特定重大疾病保險金」之責任。若係同項特定重大疾病發生二次以上者，本公司僅對其中一次特定重大疾病負給付「特定重大疾病保險金」之責任。【保險範圍：特定傷病保險金的給付】第十七條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定傷病項目之一者，本公司按下列二者之最大值給付「特定傷病保險金」後'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 4, '特定傷病', '特定傷病保險金', '取較高：保額 × 1／保費 × 1.06', '第十七條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認罹患第二條約定特定傷病項目之一者，本公司按下列二者之最大值給付「特定傷病保險金」後，本契約效力即行終止：一、罹患特定傷病時之保險金額。二、年繳保險費總和之一點零六倍。被保險人於本契約有效期間內，不論同時或先後罹患二項特定傷病，本公司僅對其中一項特定傷病負給付「特定傷病保險金」之責任。若係同項特定傷病發生二次以上者，本公司僅對其中一次特定傷病負給付「特定傷病保險金」之責任。【分期定期保險金給付】第十八條本契約有保險金分期定期給付之指定者，自分期定期給付開始日及分期定期給付開始日之每一週月日，本公司依分期定期保險金給付期間及第二條定義之分期定期保險金預定利率將指定保險金換算成每月初應給付之金額，按'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 5, '完全失能', '完全失能保險金', '取較高：保額 × 1／保費 × 1.06', '第二十條被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司按下列二者之最大值給付「完全失能保險金」後，本契約效力即行終止：一、完全失能診斷確定時之保險金額。二、年繳保險費總和之一點零六倍。【保險範圍：二至六級意外失能豁免保險費】第二十一條被保險人於本契約有效且繳費期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表三所列二至六級失能程度之一者，經醫院醫師診斷確定，本公司豁免失能診斷確定日後本契約（不含附約）續期應繳之各期保險費，本契約繼續有效。但超過一百八十日致成二至六級失能程度之一者，受益人若能證明被保險人之失能與該意外傷害事故具有因果關係者，不在此限。被保險人因本次意外傷害事故'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 6, '滿期', '滿期保險金', '取較高：保額 × 1／保費 × 1.06', '第二十二條被保險人於本契約有效期間內且在保險期間屆滿時仍生存者，本公司按下列二者之最大值給付「滿期保險金」後，本契約效力即行終止：一、保險期間屆滿時之保險金額。二、年繳保險費總和之一點零六倍。【保險範圍：保險給付的限制】第二十三條本公司依第十四條約定給付「重大傷病保險金」者，除同時符合第十五條約定而應另給付「特定重大傷病保險金」外，不再負本契約其他各項保險金給付之責。本公司依第十六條、第十七條、第十九條、第二十條或第二十二條約定給付其中一項保險金者，不再負本契約各項保險金給付之責。【分期定期保險金給付約定之變更、終止及其限制】第二十四條本契約有效期間內，要保人得於保險事故發生前變更或終止約定分期定期保險金給付。計算分期'),
  ('fubon', '富邦人壽金卡安心重大傷病保險', 7, '身故', '身故保險金或喪葬費用保險金', NULL, '第三十四條有下列情形之一者，本公司不負給付「身故保險金或喪葬費用保險金」及「完全失能保險金」的責任：一、要保人故意致被保險人於死。'),
  ('fubon', '富邦人壽醫保安心重大傷病終身健康保險', 1, '重大傷病', '重大傷病保險金', NULL, '第十四條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷，確認首次罹患第二條約定重大傷病範圍所列傷病之一，且符合下列兩項情形之一者，本公司按下表約定給付「重大傷病保險金」後，本契約效力即行終止：一、已依中央衛生主管機關所公告實施之「全民健康保險保險對象免自行負擔費用辦法」規定，取得全民健康保險保險人核發之重大傷病證明者，該證明文'),
  ('fubon', '富邦人壽醫保安心重大傷病終身健康保險', 2, '特定重大傷病', '特定重大傷病保險金', '保額 × 20%', '十五條被保險人於本契約第二保單年度起之有效期間內，經醫院醫師診斷，確認首次罹患第二條約定之重大SDG11501227/31商品代號：SDG傷病之一，而得受領第十四條約定之「重大傷病保險金」，且該項重大傷病亦同時符合第二條約定之「特定重大傷病」者，本公司除給付「重大傷病保險金」外，另按罹患特定重大傷病時之保險金額的20％給付「特定重大傷病保險金」後，本契約效力即行終止。'),
